mapper.select:
SELECT t2.*
FROM
(
    SELECT * FROM
    (
        SELECT
            t1.*,
            IF (
            FIND_IN_SET( ${parentIdColumnName}, @pids ) > 0,
            @pids := CONCAT( @pids, ',', ${idColumnName} ), '0' ) AS ischild
        FROM
        (
            SELECT * FROM ${tableName} AS t


                    ${logicDeleteSql}


            ORDER BY t.${idColumnName} ASC
        ) t1,
        ( SELECT @pids := #{id} ) t2
    ) t3
    WHERE
        ischild != '0'

            OR ${idColumnName} = #{id}

) t1
LEFT JOIN ${tableName} t2 ON t1.${idColumnName} = t2.${idColumnName}

WITH SubRecords(

        ${columnName}
    ,
    Level
) AS (
    SELECT

            ${columnName}
        ,
        1 AS Level
    FROM ${tableName}
    WHERE
        ${parentIdColumnName} = #{id}

            AND ${logicDeleteSql}

    UNION ALL
    SELECT

            t.${columnName}
        ,
        sr.Level + 1
    FROM ${tableName} t
    INNER JOIN SubRecords sr ON t.${parentIdColumnName} = sr.${idColumnName}


            AND t.${logicDeleteSql}


)
SELECT *
FROM (
    SELECT *,
        CASE WHEN ${idColumnName} = #{id} THEN 0 ELSE Level END AS SortLevel
    FROM SubRecords
    UNION ALL
    SELECT

            ${columnName}
        ,
        0 AS Level,
        0 AS SortLevel
    FROM ${tableName}
    WHERE
        ${idColumnName} = #{id}
        AND ${parentIdColumnName} != #{id}

            AND ${logicDeleteSql}

) AS CombinedResults
ORDER BY SortLevel, id ASC
